mapper.sql:
FROM analytics_recommendation_exposure
WHERE user_id > 0

    AND exposure_time >= #{startTime}

mapper.select:
SELECT COUNT(*) AS attributedPurchaseUsers, SUM(CASE WHEN repurchase.user_id IS NOT NULL THEN 1 ELSE 0 END) AS repurchaseUsers FROM ( SELECT user_id, MIN(purchase_time) AS firstPurchaseTime FROM analytics_recommendation_exposure WHERE user_id > 0 AND purchase_time IS NOT NULL
AND purchase_time >= #{startTime}
GROUP BY user_id ) seed LEFT JOIN ( SELECT DISTINCT fp.user_id FROM ( SELECT user_id, MIN(purchase_time) AS firstPurchaseTime FROM analytics_recommendation_exposure WHERE user_id > 0 AND purchase_time IS NOT NULL
AND purchase_time >= #{startTime}
GROUP BY user_id ) fp INNER JOIN `order` o ON o.user_id = fp.user_id AND o.status IN (1, 2, 3) AND o.create_time > fp.firstPurchaseTime AND o.create_time <= DATE_ADD(fp.firstPurchaseTime, INTERVAL 7 DAY) ) repurchase ON repurchase.user_id = seed.user_id
